import React, { useEffect, useRef, useState } from 'react';
import { Play, Square, Loader2 } from 'lucide-react';

interface PersonaScriptPlayerProps {
  /** Voice id, used to resolve the shipped sample and its cache state. */
  voiceId: string;
  name: string;
  audioUrl?: string;
  /** Script text, shown alongside the player. */
  script: string;
  compact?: boolean;
  className?: string;
}

/**
 * Plays the persona's pre-rendered script narration.
 *
 * The audio playing through this component is that voice's own persona script,
 * generated by the app's local synthesis engine, so narration and portrait
 * describe the same character.
 */
export const PersonaScriptPlayer: React.FC<PersonaScriptPlayerProps> = ({
  voiceId,
  name,
  audioUrl,
  script,
  compact = false,
  className = '',
}) => {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [progress, setProgress] = useState(0);

  // Another persona starting playback must stop this one.
  useEffect(() => {
    const handleOther = (event: Event) => {
      const detail = (event as CustomEvent<{ voiceId: string }>).detail;
      if (detail?.voiceId !== voiceId && audioRef.current && !audioRef.current.paused) {
        audioRef.current.pause();
        audioRef.current.currentTime = 0;
      }
    };
    window.addEventListener('vocalis:persona-play', handleOther as EventListener);
    return () => window.removeEventListener('vocalis:persona-play', handleOther as EventListener);
  }, [voiceId]);

  useEffect(() => {
    setIsPlaying(false);
    setIsLoading(false);
    setHasError(false);
    setProgress(0);
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
  }, [audioUrl]);

  const toggle = () => {
    const audio = audioRef.current;
    if (!audio || !audioUrl) return;

    if (isPlaying) {
      audio.pause();
      audio.currentTime = 0;
      setIsPlaying(false);
      setProgress(0);
      return;
    }

    setIsLoading(true);
    setHasError(false);
    window.dispatchEvent(new CustomEvent('vocalis:persona-play', { detail: { voiceId } }));
    audio
      .play()
      .then(() => {
        setIsPlaying(true);
        setIsLoading(false);
      })
      .catch(() => {
        setIsLoading(false);
        setHasError(true);
      });
  };

  return (
    <div className={`flex items-center gap-2 ${className}`}>
      <audio
        ref={audioRef}
        src={audioUrl}
        preload="none"
        onEnded={() => {
          setIsPlaying(false);
          setProgress(0);
        }}
        onTimeUpdate={(e) => {
          const el = e.currentTarget;
          if (el.duration) setProgress((el.currentTime / el.duration) * 100);
        }}
        onError={() => setHasError(true)}
      />
      <button
        type="button"
        onClick={toggle}
        disabled={!audioUrl || hasError}
        title={hasError ? 'Sample audio unavailable' : `Play ${name}'s script`}
        aria-label={isPlaying ? `Stop ${name}'s script` : `Play ${name}'s script`}
        className={`relative shrink-0 flex items-center justify-center rounded-xl font-semibold transition-all cursor-pointer overflow-hidden ${
          compact ? 'h-8 w-8' : 'h-9 px-3 gap-1.5 text-xs'
        } ${
          isPlaying
            ? 'bg-rose-600 hover:bg-rose-500 text-white'
            : 'bg-indigo-600 hover:bg-indigo-500 text-white'
        } disabled:opacity-40 disabled:cursor-not-allowed`}
      >
        {isPlaying && (
          <span
            className="absolute inset-0 bg-rose-400/25 origin-left pointer-events-none"
            style={{ transform: `scaleX(${progress / 100})` }}
          />
        )}
        <span className="relative flex items-center gap-1.5">
          {isLoading ? (
            <Loader2 className={`animate-spin ${compact ? 'w-3.5 h-3.5' : 'w-3.5 h-3.5'}`} />
          ) : isPlaying ? (
            <Square className="w-3 h-3 fill-current" />
          ) : (
            <Play className="w-3 h-3 fill-current" />
          )}
          {!compact && <span>{isPlaying ? 'Stop' : 'Script'}</span>}
        </span>
      </button>
      {!compact && (
        <span className="text-[10px] text-slate-400 font-mono truncate" title={script}>
          {hasError ? 'sample unavailable' : 'persona script'}
        </span>
      )}
    </div>
  );
};
